import pandas as pd

def clean(df):
    allowed = ["Electronics", "Accessories", "Furniture", "Office Supplies"]
    allowed_lower = [c.lower() for c in allowed]

    def correct_category(cat):
        lower_cat = cat.lower()
        if lower_cat in allowed_lower:
            return allowed[allowed_lower.index(lower_cat)]
        else:
            if lower_cat == "furnture":
                return "Furniture"
            elif lower_cat == "furniure":
                return "Furniture"
            elif lower_cat == "furntue":
                return "Furniture"
            else:
                return None
    df["Category"] = df["Category"].apply(correct_category)
    df = df[df["Category"].notna() & df["Category"].isin(allowed)]

    allowed_regions = ["North", "South", "East", "West"]
    allowed_regions_lower = [r.lower() for r in allowed_regions]

    def correct_region(region):
        if pd.isna(region):
            return None
        lower_region = region.lower()
        if lower_region in allowed_regions_lower:
            return allowed_regions[allowed_regions_lower.index(lower_region)]
        else:
            if lower_region == "north ":
                return "North"
            elif lower_region == "south ":
                return "South"
            elif lower_region == "east ":
                return "East"
            elif lower_region == "west ":
                return "West"
            else:
                return None
    df["Region"] = df["Region"].apply(correct_region)
    df = df[df["Region"].notna() & df["Region"].isin(allowed_regions)]

    df = df[df["Quantity"] >= 1]
    df = df[df["Price"] >= 0]
    return df

def answer(df):
    grouped = df.groupby("Category")["Price"].mean()
    return {category: mean for category, mean in grouped.items()}
